2628	\end{lemma}
2629	\begin{proof}
2630		\leanok
2631		\uses{def:cl-func}
2632		Adjoin $k-\ell$ empty factor spaces with zero linear maps before the given representation. Each added linear contribution is zero, so the represented function and its support are unchanged.
2633	\end{proof}
2634	
