2823	\begin{definition}[Typed conditionally linear functions]\label{def:typed-cl-functions}
2824		\lean{MIPStarRE.QPBT.IsTypedCondLinearFamily}
2825		\uses{def:cl-func}
2826		Let $\mathcal T$ be a set (the \emph{type set}) and let $V$ be $\F^n$ for some integer $n \ge 0$. A \emph{$\mathcal T$-typed family of $\ell$-level conditionally linear functions} (implicitly, \emph{on $V$}) is a collection $\{L_t\}_{t \in \mathcal T}$ such that, for each $t \in \mathcal T$, $L_t$ is an $\ell$-level conditionally linear function on $V$. Finiteness of $\mathcal T$ is not needed for this pointwise condition, so the definition applies to an arbitrary type set. A finite type set is required from Definition~\ref{def:graph-distribution} onwards, where $\mathcal T$ indexes a distribution. The source states the definition for a finite type set, and every type set occurring below is finite.
2827	\end{definition}
