2830	% normalization 1/(2m-k) below is undefined. The source
2831	% (references/qpbt-paper/07_types.tex:65-82) leaves this boundary hypothesis implicit.
2832	\begin{definition}[Graph distribution]\label{def:graph-distribution}
2833		\lean{MIPStarRE.QPBT.graphDistribution}
2834		\leanok
2835		Let $G = (U, E)$ be an undirected graph with vertex set $U$ and nonempty edge set $E$. Edges in $E$ are written as multisets $\{u, v\}$ of two vertices; the case $u = v$ represents a self-loop. Suppose there are $m \ge 1$ edges, $k$ of which are self-loops. Then the \emph{graph distribution $\mu_G$ of $G$} is the distribution over $U \times U$ such that for every $(u,v) \in U \times U$,
2836		\[
2837			\mu_G(u, v) =
2838			\begin{cases}
2839				1/(2m-k) & \text{if } \{u,v\} \in E\,,\\
2840				0 & \text{otherwise}\,.
2841			\end{cases}
2842		\]
2843		This is identical to the uniform distribution over ordered pairs $(u,v) \in U \times U$ such that $\{u,v\} \in E$: each edge that is not a self-loop contributes two ordered pairs, and each self-loop contributes one, whence the normalization $2m-k$.
